#!/bin/bash
cd /mnt/data/P95_20261126
for f in "$@"; do
 /tmp/narvenv/bin/python features.py 4 "$f" >"feature4_$f.log" 2>&1 && /tmp/narvenv/bin/python features.py 1 "$f" >"feature1_$f.log" 2>&1 || { echo "FAIL $f"; exit 1; }
 echo "PASS $f"
done

"""No raw, residual, labels or identity keys read; only hashed feature freezes."""
import json,sys,hashlib
from pathlib import Path
import duckdb
O=Path(__file__).parent; stage=sys.argv[1]; threads=int(sys.argv[2]); S=O/stage; S.mkdir(exist_ok=True)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();dump=lambda p,x:p.write_text(json.dumps(x,indent=2,default=str)+'\n')
fs='jv jd js jb tb jt tp pb sw'.split(); years=(2017,2021) if stage=='dev' else (2022,2023); defs={'astar':None}|{f'{f}_w{w}':(f,w/100) for f in fs for w in [10,20]}
if stage=='val':defs={k:defs[k] for k in ['astar']+json.loads((O/'shortlist.json').read_text())['models']}
c=duckdb.connect();c.execute(f"set threads={threads};set memory_limit='1200MB';set temp_directory='/tmp/p95scorespill'")
base=['runner_id','race_id','race_date','venue','horse_no','field_size','distance_m','n_hl60','s_astar','r_astar','reason_astar','ambiguous','band'];manifest={}
assert c.execute("select list(horse_no order by round(s,12) desc,horse_no) from (values(1,0.5000000000001),(2,0.5000000000002),(3,0.5000000000006)) t(horse_no,s)").fetchone()[0]==[3,1,2]
for name,term in defs.items():
 f=term[0] if term else 'jv'; p=O/f'features_{f}_t4.parquet';a=json.loads((O/f'feature_audit_{f}.json').read_text()); b=json.loads((O/f'feature_parity_{f}.json').read_text());assert sha(p)==a['features_sha']==b['sha'] and b['status']=='PASS'
 allowed=set(base+[f+'_term',f+'_apply']+[f'_{k}{i}' for i in [] for k in []]+[f'{f}_{k}{i}' for i in range(4) for k in ['n','e','excluded']]); cols={x[0] for x in c.execute(f"describe select * from '{p}'").fetchall()};assert cols==allowed, (f,cols-allowed,allowed-cols)
 score='s_astar' if not term else f's_astar+{term[1]}*{f}_term'; app='false' if not term else f'{f}_apply';
 q=f'''with s as(select {','.join(base)}, {score} score,{app} applied from read_parquet('{p}') where year(race_date) between {years[0]} and {years[1]}),r as(select *,case when score is not null then row_number() over(partition by race_id order by round(score,12) desc nulls last,horse_no) end pred_rank from s) select runner_id,race_id,race_date,venue,horse_no,distance_m,n_hl60,band,r_astar,reason_astar,score,applied,pred_rank from r order by runner_id'''
 out=S/f'{name}.parquet'
 if threads==4:
  c.execute(f"copy ({q}) to '{out}' (format parquet,compression zstd)");manifest[name]=sha(out);assert c.execute(f"select count(*) from '{out}' where score is not null and not isfinite(score)").fetchone()[0]==0
  if name=='astar':assert c.execute(f"select count(*) from '{out}' where pred_rank is distinct from r_astar").fetchone()[0]==0
 else:
  old=json.loads((S/'prediction_manifest.json').read_text());assert sha(out)==old['files'][name]
  n=c.execute(f'''select count(*) from ({q}) a full join read_parquet('{out}') b using(runner_id) where a.runner_id is null or b.runner_id is null or a.pred_rank is distinct from b.pred_rank or a.applied is distinct from b.applied or (a.score is null)<>(b.score is null) or abs(a.score-b.score)>1e-12 or a.reason_astar is distinct from b.reason_astar''').fetchone()[0];assert n==0,(name,n);manifest[name]=0
 print(stage,threads,name,flush=True)
if threads==4:dump(S/'prediction_manifest.json',{'stage':stage,'years':years,'files':manifest,'models':defs,'status':'FROZEN_T4'})
else:dump(S/'prediction_parity.json',{'status':'PASS','prediction_manifest_sha256':sha(S/'prediction_manifest.json'),'mismatch':manifest})

import csv,json,sys,hashlib
from pathlib import Path
import numpy as np
O=Path(__file__).parent; stage=sys.argv[1];S=O/stage;sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest(); read=lambda p:list(csv.DictReader(p.open()));dump=lambda p,x:p.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
rows={(r['model'],int(r['yr'])):{k:int(v) for k,v in r.items() if k not in ('model','yr')} for r in read(S/'metrics.csv')};models=sorted(set(n for n,y in rows if n!='astar'));base=rows['astar',0]
def dif(n,y):
 a,b=rows[n,y],rows['astar',y];den=b['scored_races'];assert all(a[k]==b[k] for k in ['eligible','runners','scored_runners','scored_races','place_available']); d={k:a[k]-b[k] for k in ['wins','top3','winner3','hits','place']};return d,den
def guard(d,den,track):return d['wins']*100/den>=-.1 and d['top3']*100/den>=-.5 and d['winner3']*100/den>=-.5 and (track!='PLACE' or d['hits']>=0)
tracks={'WIN':'wins','PLACE':'place'}; dec=[]
if stage=='dev':
 winners={}
 for track,key in tracks.items():
  cand=[]
  for n in models:
   d,den=dif(n,0);qual=d[key]>0 and guard(d,den,track);dec.append({'track':track,'model':n,'delta':d,'den':den,'qualifies':qual})
   if qual:cand.append(n)
  if cand:winners[track]=min(cand,key=lambda n:(-dif(n,0)[0][key],int(n.rsplit('w',1)[1]),n))
 out={'status':'FROZEN_BEFORE_VALIDATION','metrics_sha':sha(S/'metrics.csv'),'selected':winners,'models':list(dict.fromkeys(winners.values())),'decisions':dec,'validation_opened':False};dump(O/'shortlist.json',out);print(json.dumps(winners),flush=True)
else:
 sl=json.loads((O/'shortlist.json').read_text());assert set(models)==set(sl['models']);block=read(S/'blocks.csv');rng=np.random.default_rng(20261124)
 for track,n in sl['selected'].items():
  key=tracks[track];d,den=dif(n,0);annual={str(y):dif(n,y)[0] for y in (2022,2023)};qual=d[key]>0 and guard(d,den,track) and all(x[key]>0 and guard(x,dif(n,int(y))[1],track) for y,x in annual.items()); metric='delta_win' if track=='WIN' else 'delta_place';
  # paired date blocks stratified by year, and venue-day sensitivity
  cis={}
  for mode in ['date','venue_date']:
   agg={}
   for r in block:
    if r['model']!=n:continue
    ky=(r['race_date'],r['venue'] if mode=='venue_date' else '')
    a=agg.setdefault(ky,[0,0]);a[0]+=int(r['den']);a[1]+=int(r[metric])
   samples=np.zeros((2000,2),dtype=np.int64)
   for y in (2022,2023):
    ar=np.array([v for k,v in sorted(agg.items()) if k[0].startswith(str(y))]);ix=rng.integers(len(ar),size=(2000,len(ar)));samples+=ar[ix].sum(axis=1)
   cis[mode]=(np.quantile(samples[:,1]*100/samples[:,0],[.025,.975])).tolist()
  dec.append({'track':track,'model':n,'delta':d,'den':den,'annual':annual,'primary_delta_per100':d[key]*100/den,'ci95':cis,'qualified':qual})
 out={'status':'VALIDATION_COMPLETE','shortlist_sha':sha(O/'shortlist.json'),'metrics_sha':sha(S/'metrics.csv'),'decisions':dec,'selected':{r['track']:r['model'] for r in dec if r['qualified']},'confirmation_opened':False};dump(O/'validation_decision.json',out);print(json.dumps(out),flush=True)

import sys,json,hashlib,shutil,subprocess,os,tempfile
from pathlib import Path
import pyarrow.parquet as pq,pyarrow as pa
O=Path(__file__).parent;sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();stage=sys.argv[1]; fs='jv jd js jb tb jt tp pb sw'.split();S=O/stage
# Verify source gate on tiny malicious fixtures even if the manifest is updated to match the malicious bytes.
with tempfile.TemporaryDirectory(prefix='p95_iso_') as td:
 d=Path(td);shutil.copy(O/'score.py',d/'score.py');base=pq.ParquetFile(O/'features_jv_t4.parquet').read_row_group(0).slice(0,1);reject=[]
 for col in ['popularity','payout_yen','overall_record_raw','status','track_condition','body_weight_kg','finish_position']:
  p=d/'features_jv_t4.parquet';pq.write_table(base.append_column(col,pa.array([1])),p);(d/'feature_audit_jv.json').write_text(json.dumps({'features_sha':sha(p)}));(d/'feature_parity_jv.json').write_text(json.dumps({'status':'PASS','sha':sha(p)}));r=subprocess.run([sys.executable,str(d/'score.py'),'dev','4'],capture_output=True,text=True);assert r.returncode!=0 and 'AssertionError' in r.stderr and col in r.stderr,(col,r.stderr);reject.append(col)
 # Real score-only directory: only derived freeze + metadata + shortlist. No evaluator labels.
 for f in fs:
  for n in [f'features_{f}_t4.parquet',f'feature_audit_{f}.json',f'feature_parity_{f}.json']:
   p=d/n
   if p.exists():p.unlink()
   os.link(O/n,p)
 if stage=='val':shutil.copy(O/'shortlist.json',d/'shortlist.json')
 original=json.loads((S/'prediction_manifest.json').read_text())['files'];
 def test():
  r=subprocess.run([sys.executable,str(d/'score.py'),stage,'4'],capture_output=True,text=True);assert r.returncode==0,r.stderr
  actual=json.loads((d/stage/'prediction_manifest.json').read_text())['files'];assert actual==original
 test();(d/'labels.parquet').write_bytes(b'corrupted forbidden labels');test()
(O/f'isolation_{stage}.json').write_text(json.dumps({'status':'PASS','forbidden_columns_rejected':reject,'no_labels_and_poisoned_labels_same_prediction_hashes':True,'not_os_sandbox':True},indent=2)+'\n')

import json,hashlib,csv
from pathlib import Path
import numpy as np
O=Path(__file__).parent;C=O/'confirm_run';S=C/'confirm';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();read=lambda p:list(csv.DictReader(p.open()));rows={(r['model'],int(r['yr'])):{k:int(v) for k,v in r.items() if k not in ('model','yr')} for r in read(S/'metrics.csv')};base=rows['astar',0];m=rows['jb_w20',0];d={k:m[k]-base[k] for k in ['wins','top3','winner3','hits','place']};den=base['scored_races'];assert all(m[k]==base[k] for k in ['eligible','runners','scored_runners','scored_races','place_available']);annual={}
for y in (2024,2025):annual[str(y)]={k:rows['jb_w20',y][k]-rows['astar',y][k] for k in d}
block=read(S/'blocks.csv');rng=np.random.default_rng(20261124);ci={}
for mode in ['date','venue_date']:
 agg={}
 for r in block:
  if r['model']!='jb_w20':continue
  ky=(r['race_date'],r['venue'] if mode=='venue_date' else '');a=agg.setdefault(ky,[0]*4);a[0]+=int(r['den']);a[1]+=int(r['delta_place']);a[2]+=int(r['delta_hits']);a[3]+=int(r['delta_win'])
 samples=np.zeros((2000,4),dtype=np.int64)
 for y in (2024,2025):
  ar=np.array([v for k,v in sorted(agg.items()) if k[0].startswith(str(y))]);ix=rng.integers(len(ar),size=(2000,len(ar)));samples+=ar[ix].sum(axis=1)
 ci[mode]={k:np.quantile(samples[:,i]*100/samples[:,0],[.025,.975]).tolist() for i,k in [(1,'place'),(2,'hits'),(3,'wins')]}
seg=read(S/'segments.csv');vg={}
for r in seg:
 v=vg.setdefault(r['venue'],{'den':0,'place':0,'win_delta':0,'hit_delta':0});sign=1 if r['model']=='jb_w20' else -1
 if sign==1:v['den']+=int(r['scored_races'])
 v['place']+=sign*int(r['place']);v['win_delta']+=sign*int(r['wins']);v['hit_delta']+=sign*int(r['hits'])
review=[dict(venue=k,**v) for k,v in vg.items() if v['den']>=500 and (v['place']*100/v['den'] < -2 or v['win_delta']*100/v['den'] < -2 or v['hit_delta']*100/v['den'] < -2)]
gates={'primary_min_0_3':d['place']*100/den>=.3,'ci_positive':ci['date']['place'][0]>0,'win_loss_le_0_1pp':d['wins']*100/den>=-.1,'top1_top3_loss_le_0_5pp':d['top3']*100/den>=-.5,'winner_in_top3_loss_le_0_5pp':d['winner3']*100/den>=-.5,'total_hits_non_decrease':d['hits']>=0,'coverage_same':True,'full_intent_primary_non_decrease':d['place']>=0,'venue_review_no_material_decline':not review}
passed=all(gates.values());out={'status':'PLACE_RESEARCH_CANDIDATE_PROMOTED' if passed else 'NOT_PROMOTED_CONFIRMATION_GATE','candidate_sha':sha(O/'candidate_config.json'),'prediction_manifest_sha':sha(S/'prediction_manifest.json'),'metrics_sha':sha(S/'metrics.csv'),'native':{'astar':base,'jb_w20':m},'delta':d,'annual':annual,'per100':{k:100*v/den for k,v in d.items()},'ci95':ci,'gates':gates,'venue_review':review,'selected_for_p10_win':'P8-Astar-r1','selected_for_p10_place':'P95-PLACE-JB-r1' if passed else None,'confirmation_opened':True,'independent_blind':False,'production_approved':False,'2026_used':False};(O/'confirmation_result.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out),flush=True)

